-- Generated fields are maintained for all alert writers, including older images.
ALTER TABLE alerts ADD COLUMN inbox_project VARCHAR(255) GENERATED ALWAYS AS (lower(coalesce(CASE JSON_EXTRACT(payload, '$."project_id"') WHEN 'null' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(payload, '$."project_id"')) END, CASE JSON_EXTRACT(payload, '$."project"') WHEN 'null' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(payload, '$."project"')) END, CASE JSON_EXTRACT(payload, '$."project_name"') WHEN 'null' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(payload, '$."project_name"')) END, CASE JSON_EXTRACT(payload, '$."application"') WHEN 'null' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(payload, '$."application"')) END, CASE JSON_EXTRACT(JSON_EXTRACT(payload, '$."labels"'), '$."project_id"') WHEN 'null' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(JSON_EXTRACT(payload, '$."labels"'), '$."project_id"')) END, CASE JSON_EXTRACT(JSON_EXTRACT(payload, '$."labels"'), '$."project"') WHEN 'null' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(JSON_EXTRACT(payload, '$."labels"'), '$."project"')) END, CASE JSON_EXTRACT(JSON_EXTRACT(payload, '$."labels"'), '$."project_name"') WHEN 'null' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(JSON_EXTRACT(payload, '$."labels"'), '$."project_name"')) END, CASE JSON_EXTRACT(JSON_EXTRACT(payload, '$."labels"'), '$."application"') WHEN 'null' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(JSON_EXTRACT(payload, '$."labels"'), '$."application"')) END, ''))) VIRTUAL;
ALTER TABLE alerts ADD COLUMN inbox_canonical_incident_id VARCHAR(64) GENERATED ALWAYS AS (CASE JSON_EXTRACT(JSON_EXTRACT(JSON_EXTRACT(payload, '$."metadata"'), '$."deduplication"'), '$."canonical_incident_id"') WHEN 'null' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(JSON_EXTRACT(JSON_EXTRACT(payload, '$."metadata"'), '$."deduplication"'), '$."canonical_incident_id"')) END) VIRTUAL;
ALTER TABLE alerts ADD INDEX idx_alerts_inbox_scope (tenant_id,inbox_canonical_incident_id,inbox_project,created_at), ALGORITHM=INPLACE, LOCK=NONE;
